public class JSumDigits {
	public static void main(String[] args) {
		//Alkhatwa 1: ta3reef al-mutaghayyirat allati nahtajuha li-hadha al-barnamaj
		int num = 1234;
		int lastDigit;
		int total = 0;
		//Alkhatwa 2: jama3 al-arqam lil-3adad
		do {
			//Alkhatwa 2.1: istikhraj al-raqm al-akhir min al-3adad
			lastDigit = num % 10;
			//Alkhatwa 2.2: zid al-raqm al-akhir ila majmu3 al-arqam ila al-aan
			total = total + lastDigit;
			//Alkhatwa 2.3: izala al-raqm al-akhir min al-3adad
			num = num / 10;
			System.out.println("al-raqm al-akhir: "+lastDigit+", al-majmu3: "+total+", al-3adad: "+num);
		} while (num > 0);
		System.out.println("majmu3 al-arqam: " + total);
	}
}
